from torch.utils.cpp_extension import load_inline

# Define CUDA kernel for matrix multiplication with shared memory
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    extern __shared__ float shared_mem[];
    float* tileA = shared_mem;
    float* tileB = &shared_mem[blockDim.x * blockDim.y];

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = blockIdx.y * blockDim.y + ty;
    int col = blockIdx.x * blockDim.x + tx;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < gridDim.x; t++) {
        // Load tile of A into shared memory
        int tile_col = t * blockDim.x + tx;
        if (row < N && tile_col < N) {
            tileA[ty * blockDim.x + tx] = A[row * N + tile_col];
        } else {
            tileA[ty * blockDim.x + tx] = 0.0f;
        }

        // Load tile of B into shared memory
        int tile_row = t * blockDim.y + ty;
        if (tile_row < N && col < N) {
            tileB[ty * blockDim.x + tx] = B[tile_row * N + col];
        } else {
            tileB[ty * blockDim.x + tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum for the tile
        for (int k = 0; k < blockDim.x; k++) {
            sum += tileA[ty * blockDim.x + k] * tileB[k * blockDim.x + tx];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

