    size_t shared_mem_size = 2 * block_size * block_size * sizeof(float);

    // Launch kernel
    matmul_kernel<<<blocks, threads, shared_mem_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

